REPLACE INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `QuestSortID`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`) VALUES (1660000, 2, 6, 3, 9, 3, 8, 'Bookworm', 'Speak with Seminarian Moroi, brother of Bianca Spada.', '<A woman greets you, visibly agitated. A sharp mix of anger and worry flashes in her eyes.>$b$bSorry, I didn''t mean to make a scene, but... that blasted brother of mine, always buried in his books! I''ve been out here forever, yelling my lungs out, and nothing. The guards have already warned me about "disturbing the abbey''s peace" one more time.$b$bWould you mind going in there and dragging him out by the ears if you have to? Our mother''s on her deathbed, and I''ve traveled a long way to fetch him so he can say goodbye. The ungrateful wretch.', '');
REPLACE INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `QuestSortID`, `RewardXPDifficulty`, `RewardMoney`, `Flags`, `RequiredItemId1`, `RequiredItemCount1`, `RequiredItemId2`, `RequiredItemCount2`, `RequiredItemId3`, `RequiredItemCount3`, `RequiredItemId4`, `RequiredItemCount4`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`) VALUES (1660001, 2, 6, 3, 9, 4, 15, 8, 559130, 1, 559131, 1, 559132, 1, 559133, 1, 'Knowledge Corrupts', 'Recover the missing pages from Moroi''s unclassified manuscript, scattered throughout the abbey.', 'Go on, take a look.$b$b<Moroi gestures toward the book holding his attention: a thin, battered manuscript, not unlike its reader.>$b$bI stumbled across it in the library; it''s not listed in the abbey''s records. I think it''s some sort of chronicle about an old abbess accused of heresy. In my haste, I''ve misplaced several pages. I''ve been trying to piece them back together, but some are still missing.$b$bCould you have a look around the abbey and recover the pages I lost? This is a banned book; if anyone finds out I''ve been poking my nose where it doesn''t belong, they''ll ship me back home... to my sister.$b$bDo me a mercy, will you?', 'Return to Moroi.');
REPLACE INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `QuestSortID`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`) VALUES (1660002, 2, 6, 3, 9, 4, 8, 'The Ruins of Northshire', 'Locate the cellar entrance to the Secret Inquisitorial Dungeon.', 'A visit to the dungeon where the abbess was tried might shed some light...$b$bAccording to the book, the now-abandoned town of Northshire held a secret entrance to the Inquisitorial Dungeon.$b$bI''ll mark it on your map, but tread carefully. No one''s set foot in that place for years... I''d rather not imagine what vermin have claimed its ruins.', 'Speak with the spectral priestess.');
REPLACE INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `QuestSortID`, `RewardXPDifficulty`, `Flags`, `RewardItem1`, `RewardAmount1`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`) VALUES (1660003, 2, -1, 3, 9, 5, 8, 5571, 1, 'Accursed Sisterhood', 'Purify the belongings of the former abbess, scattered throughout the Secret Inquisitorial Dungeon.', 'The way is shut. The abbess cursed those who judged her, binding them to wander as restless spirits.$b$bThose who died are still chained by her power. The dignity and belongings they stripped from her became shackles. A simple prayer. A sincere plea. That would be enough...$b$bThey''ll find no rest until someone purifies the abbess''s relics, scattered throughout the dungeon.$b$bBut the Dead guard them well. And so, the way remains shut.', 'Speak with Sister Alma.');
REPLACE INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `QuestSortID`, `SuggestedGroupNum`, `RewardXPDifficulty`, `RewardMoney`, `Flags`, `RewardItem1`, `RewardAmount1`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`) VALUES (1660004, 2, -1, 3, 9, 2, 7, 35, 8, 559182, 1, 'Words that Shepherd Madness', 'Find the hidden path leading to the top of the waterfall and confront the sins of the former abbess of Northshire.', 'Sitis was... a storm. Her teachings were unorthodox; dangerous, even. Many students left the Church because of her.$b$bSo when the inquisitorial court summoned me to testify, I agreed to speak against her.$b$bI had learned she was holding secret gatherings with her closest circle at an old manor above the waterfall. In those meetings, Sitis spoke of the Light, of life, of death...$b$bAnd of the nature of the Shadow.$b$bHer heresy still stains that land. But beware if you go there; she had no shortage of followers, and the Inquisition never caught them all...', 'Return to Moroi and report what you''ve discovered about the former abbess and her crimes.');
REPLACE INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `QuestSortID`, `RewardXPDifficulty`, `RewardMoney`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`) VALUES (1660005, 2, -1, 3, 9, 6, 20, 8, 'The Threat Swept Downstream', 'Defeat the Defias lurking in the ruined tower and thin the ranks of the Shadewell murlocs atop the waterfall, across the rope bridge.', 'I need... help.$b$b<The soldier''s voice comes ragged, choked with pain. Each grimace is a fresh wound.>$b$bI was ordered to find the murloc village, to cut off their threat. But, as you can see, the road has not been kind to me. And worse yet: the only path to the upper river runs straight through that tower.$b$b<He nods weakly toward the looming, ruined structure.>$b$bYou, though... you might succeed where I could not.$b$bDeal with the Defias infesting the tower, thin the ranks of the murlocs above the falls, and you''ll be doing me a favor the whole kingdom will thank you for.', 'Return to the injured guard.');
REPLACE INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `QuestSortID`, `RewardXPDifficulty`, `Flags`, `RequiredItemId1`, `RequiredItemCount1`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`) VALUES (1660036, 2, -1, 3, 9, 5, 0, 559160, 3, 'Oracular Idol', 'Collect three Prophet''s Oracular Orbs from the murloc oracles roaming the Shadewell Spring.', '<After the spasms and convulsions of a brutal death, the murloc slumps into the wet earth, dropping a sphere that rolls to a stop at your boots.>$b$b<On closer inspection, you realize it''s no common jewel at all; it''s an eyeball. Its slick surface reflects vague images that do not match the world around you. It''s as if... it''s as if it shows you what''s yet to come.>$b$b<Perhaps you should strike down the other oracles and examine their strange, blind eyes.>', 'Find someone at the Abbey to share your discovery with.');
REPLACE INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `QuestSortID`, `SuggestedGroupNum`, `RewardXPDifficulty`, `Flags`, `RewardChoiceItemID1`, `RewardChoiceItemQuantity1`, `RewardChoiceItemID2`, `RewardChoiceItemQuantity2`, `RewardChoiceItemID3`, `RewardChoiceItemQuantity3`, `RewardChoiceItemID4`, `RewardChoiceItemQuantity4`, `RewardChoiceItemID5`, `RewardChoiceItemQuantity5`, `RewardChoiceItemID6`, `RewardChoiceItemQuantity6`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`) VALUES (1660038, 2, -1, 3, 9, 2, 3, 8, 559176, 1, 559177, 1, 559178, 1, 559179, 1, 559180, 1, 559181, 1, 'The Saddest Among Us', 'Defeat the Cursed Censor in the Secret Inquisitorial Dungeon.', 'Slave to the hunger of the flames, always demanding more books to devour. When there were no more blasphemies left, they turned on the sacred texts instead.$b$bThe fire burns in his hollow sockets; there are no more tears left to shed.$b$bOnly death can release the Cursed Censor...', 'Return to Sister Alma.');
